<?php
if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once '../config/security.php';require_once '../config/database.php';$role=$_SESSION['role']??'';$uid=(int)($_SESSION['user_id']??0);if(!$uid){header('Location: ../auth/login.php');exit;}$msg='';$msgType='';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='send'){$recipient=(int)($_POST['recipient_id']??0);$subject=trim($_POST['subject']??'');$body=trim($_POST['message']??'');if(!csrf_valid($_POST['csrf_token']??null)){$msg='Session expired. Refresh and try again.';$msgType='error';}elseif(!$recipient||$subject===''||$body===''){$msg='Choose a recipient and complete the subject and message.';$msgType='error';}else{$st=$conn->prepare("SELECT id FROM users WHERE id=? AND status='active' LIMIT 1");$st->bind_param('i',$recipient);$st->execute();$ok=$st->get_result()->fetch_assoc();$st->close();if(!$ok){$msg='Recipient is not available.';$msgType='error';}else{$st=$conn->prepare('INSERT INTO user_messages(sender_id,recipient_id,subject,message) VALUES(?,?,?,?)');$st->bind_param('iiss',$uid,$recipient,$subject,$body);$st->execute();$st->close();$msg='Message sent.';$msgType='success';}}}
$view=(int)($_GET['view']??0);$selected=null;if($view){$st=$conn->prepare("SELECT m.*,CONCAT(s.first_name,' ',s.last_name) sender_name,CONCAT(r.first_name,' ',r.last_name) recipient_name FROM user_messages m JOIN users s ON s.id=m.sender_id JOIN users r ON r.id=m.recipient_id WHERE m.id=? AND (m.sender_id=? OR m.recipient_id=?) LIMIT 1");$st->bind_param('iii',$view,$uid,$uid);$st->execute();$selected=$st->get_result()->fetch_assoc();$st->close();if($selected && (int)$selected['recipient_id']===$uid && !(int)$selected['is_read']){$st=$conn->prepare('UPDATE user_messages SET is_read=1,read_at=COALESCE(read_at,NOW()) WHERE id=?');$st->bind_param('i',$view);$st->execute();$st->close();}}
$st=$conn->prepare("SELECT m.id,m.subject,m.is_read,m.created_at,m.sender_id,m.recipient_id,CONCAT(s.first_name,' ',s.last_name) sender_name,CONCAT(r.first_name,' ',r.last_name) recipient_name FROM user_messages m JOIN users s ON s.id=m.sender_id JOIN users r ON r.id=m.recipient_id WHERE m.sender_id=? OR m.recipient_id=? ORDER BY m.created_at DESC LIMIT 100");$st->bind_param('ii',$uid,$uid);$st->execute();$messages=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
if($role==='patient'){$st=$conn->prepare("SELECT id,first_name,last_name,role FROM users WHERE status='active' AND role IN ('assistant','dentist') ORDER BY role,last_name,first_name");$st->execute();$recipients=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();}else{$st=$conn->prepare("SELECT id,first_name,last_name,role FROM users WHERE status='active' AND id<>? ORDER BY role,last_name,first_name");$st->bind_param('i',$uid);$st->execute();$recipients=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();}
require '../includes/ui.php';ui_header('Messages',$role);ui_sidebar($role,'');?><div class="page-head"><div><div class="eyebrow">MESSAGES</div><h1>Message Center</h1><div class="muted">Send and review secure messages inside the SupremeDent system.</div></div></div><?php if($msg)flash($msgType,$msg);?><section class="message-layout"><div class="card"><div class="card-heading"><div><h2>Conversations</h2><p class="muted">Newest messages first.</p></div></div><div class="message-thread"><?php if(!$messages):?><div class="empty">No messages yet.</div><?php else:foreach($messages as $m):$incoming=(int)$m['recipient_id']===$uid;?><a class="message-item <?=$incoming&&!(int)$m['is_read']?'unread':''?>" href="messages.php?view=<?=$m['id']?>"><strong><?=e($m['subject'])?></strong><small><?=$incoming?'From '.e($m['sender_name']):'To '.e($m['recipient_name'])?> · <?=e(date('M d, h:i A',strtotime($m['created_at'])))?></small></a><?php endforeach;endif;?></div></div><div><?php if($selected):?><section class="card"><div class="message-meta"><span><?=e((int)$selected['sender_id']===$uid?'To: '.$selected['recipient_name']:'From: '.$selected['sender_name'])?></span><span><?=e(date('M d, Y · h:i A',strtotime($selected['created_at'])))?></span></div><h2><?=e($selected['subject'])?></h2><div class="message-body"><?=e($selected['message'])?></div></section><?php endif;?><section class="card"><div class="card-heading"><div><h2>New Message</h2><p class="muted">Messages stay inside your SupremeDent account.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="action" value="send"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field full"><label>Recipient</label><select name="recipient_id" required><option value="">Select recipient</option><?php foreach($recipients as $r):?><option value="<?=$r['id']?>"><?=e($r['last_name'].', '.$r['first_name'].' — '.ucfirst($r['role']))?></option><?php endforeach;?></select></div><div class="field full"><label>Subject</label><input name="subject" maxlength="180" required></div><div class="field full"><label>Message</label><textarea name="message" maxlength="3000" required></textarea></div><div class="actions full"><button class="btn btn-primary" type="submit">Send Message</button></div></form></section></div></section><?php ui_footer();?>
